#!/usr/bin/env python3
"""One-file Google Colab pipeline for ranked, NASA-derived color close-ups.

Upload only this file to a Colab GPU runtime, then run for example:

    !python colab_color_pipeline.py --top 14 --download

The script installs missing Python packages, clones the Marswalk repository,
installs its embedded pipeline modules, ranks reconstructable/color-rich sols,
builds missing Navcam meshes, projects same-station Mastcam RGB, validates every
variant, and creates ``/content/color_coverage.zip``.  The ZIP contains a
``color_coverage/`` directory whose contents can be copied over the repository
root to install the generated stops and updated ``app/data.json``.

No local source checkout is needed. Downloads and completed outputs are reused
when the script is rerun with the same ``--repo-dir``.
"""
from __future__ import annotations

import argparse
import base64
import concurrent.futures as futures
import csv
import hashlib
import importlib.util
import io
import json
import math
from pathlib import Path
import shutil
import subprocess
import sys
import tarfile
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone


DEFAULT_REPO_URL = "https://github.com/Shamveel-Khan/NASA-space-apps-project.git"
WAYPOINTS_URL = "https://mars.nasa.gov/mmgis-maps/MSL/Layers/json/MSL_waypoints.json"
NAVCAM_BASE = "https://planetarydata.jpl.nasa.gov/img/data/msl/MSLNAV_1XXX/"
R_MARS = 3_396_190.0
PIPELINE_PAYLOAD_SHA256 = "a5a8c455742fbd8894cc10c4c61dc41285436f1a30856638d78a80b96a3b4be4"
EMBEDDED_PIPELINE_B64 = ""


def log(message: str) -> None:
    print(f"[{datetime.now().strftime('%H:%M:%S')}] {message}", flush=True)


def run(command: list[str], cwd: Path | None = None, check: bool = True) -> subprocess.CompletedProcess:
    log("RUN " + " ".join(map(str, command)))
    result = subprocess.run(command, cwd=cwd, check=False)
    if check and result.returncode:
        raise RuntimeError(f"Command exited with {result.returncode}: {' '.join(map(str, command))}")
    return result


def ensure_dependencies(skip: bool) -> None:
    if skip:
        return
    modules = {
        "numpy": "numpy==2.2.6",
        "scipy": "scipy==1.15.3",
        "PIL": "pillow==12.3.0",
        "matplotlib": "matplotlib==3.10.7",
        "torch": "torch",
        "transformers": "transformers==4.57.6",
    }
    missing = [package for module, package in modules.items() if importlib.util.find_spec(module) is None]
    if missing:
        log("Installing missing dependencies: " + ", ".join(missing))
        run([sys.executable, "-m", "pip", "install", "-q", *missing])
    import torch
    log(f"Torch {torch.__version__}; CUDA available={torch.cuda.is_available()}")


def safe_extract(payload: bytes, destination: Path) -> None:
    destination = destination.resolve()
    with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as archive:
        for member in archive.getmembers():
            target = (destination / member.name).resolve()
            if destination != target and destination not in target.parents:
                raise RuntimeError(f"Unsafe embedded path: {member.name}")
        try:
            archive.extractall(destination, filter="data")
        except TypeError:  # Python < 3.12 has no extraction filter argument.
            archive.extractall(destination)


def install_embedded_pipeline(repo: Path) -> None:
    compressed = base64.b64decode(EMBEDDED_PIPELINE_B64, validate=True)
    digest = hashlib.sha256(compressed).hexdigest()
    if digest != PIPELINE_PAYLOAD_SHA256:
        raise RuntimeError(f"Embedded pipeline checksum mismatch: {digest}")
    safe_extract(compressed, repo)
    required = [
        repo / "navcam3d/build_stop.py",
        repo / "navcam3d/audit_color_coverage.py",
        repo / "navcam3d/colorize_stop.py",
        repo / "navcam3d/colorize_all_stops.py",
    ]
    if not all(path.is_file() for path in required):
        raise RuntimeError("Embedded pipeline extraction is incomplete")


def prepare_repo(args: argparse.Namespace) -> Path:
    repo = args.repo_dir.resolve()
    if not (repo / ".git").exists():
        if repo.exists() and any(repo.iterdir()):
            raise RuntimeError(f"--repo-dir exists but is not an empty directory or Git checkout: {repo}")
        repo.parent.mkdir(parents=True, exist_ok=True)
        run(["git", "clone", "--depth", "1", args.repo_url, str(repo)])
    if args.revision:
        run(["git", "fetch", "--depth", "1", "origin", args.revision], cwd=repo)
        run(["git", "checkout", "--detach", "FETCH_HEAD"], cwd=repo)
    install_embedded_pipeline(repo)
    if not (repo / "app/data.json").is_file():
        raise RuntimeError("Repository has no app/data.json; it is not a compatible Marswalk checkout")
    return repo


def request_bytes(url: str, cache_path: Path, tries: int = 6, timeout: int = 60) -> bytes:
    if cache_path.is_file() and cache_path.stat().st_size:
        return cache_path.read_bytes()
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    error: Exception | None = None
    for attempt in range(tries):
        try:
            request = urllib.request.Request(url, headers={"User-Agent": "marswalk-colab-color/1.0"})
            with urllib.request.urlopen(request, timeout=timeout) as response:
                data = response.read()
            if not data:
                raise ValueError("empty response")
            temporary = cache_path.with_suffix(cache_path.suffix + ".part")
            temporary.write_bytes(data)
            temporary.replace(cache_path)
            return data
        except (OSError, ValueError, urllib.error.HTTPError) as exc:
            error = exc
            fatal = isinstance(exc, urllib.error.HTTPError) and exc.code in (401, 403, 404)
            if fatal or attempt + 1 >= tries:
                break
            delay = min(30, 2 ** attempt)
            log(f"Network retry {attempt + 2}/{tries} in {delay}s: {url} ({exc})")
            time.sleep(delay)
    raise RuntimeError(f"Unable to download {url}: {error}")


def get_json(url: str, cache_path: Path) -> dict:
    return json.loads(request_bytes(url, cache_path).decode("utf-8", errors="replace"))


def stop_rows(waypoints: dict, sol_min: int | None, sol_max: int | None) -> list[dict]:
    by_sol: dict[int, dict] = {}
    for feature in waypoints.get("features", []):
        row = feature.get("properties", {})
        try:
            sol = int(row["sol"])
            site, drive = int(row["site"]), int(row["drive"])
            float(row["lat"]); float(row["lon"])
        except (KeyError, TypeError, ValueError):
            continue
        if sol_min is not None and sol < sol_min:
            continue
        if sol_max is not None and sol > sol_max:
            continue
        previous = by_sol.get(sol)
        if previous is None or (site, drive) > (int(previous["site"]), int(previous["drive"])):
            by_sol[sol] = row
    return list(by_sol.values())


def projected_xy(lat: float, lon: float) -> tuple[float, float]:
    return R_MARS * math.radians(lon), R_MARS * math.radians(lat)


def distance_m(a: dict, b: dict) -> float:
    lat1, lon1, lat2, lon2 = map(math.radians, (float(a["lat"]), float(a["lon"]),
                                                float(b["lat"]), float(b["lon"])))
    h = math.sin((lat2-lat1)/2)**2 + math.cos(lat1)*math.cos(lat2)*math.sin((lon2-lon1)/2)**2
    return 2 * R_MARS * math.asin(min(1.0, math.sqrt(h)))


def in_window(row: dict, window: dict) -> bool:
    x, y = projected_xy(float(row["lat"]), float(row["lon"]))
    cx, cy = projected_xy(float(window["lat"]), float(window["lon"]))
    half = float(window["size_m"]) / 2
    return abs(x-cx) <= half and abs(y-cy) <= half


def navcam_folder(sol: int) -> str:
    branch = "DATA_V1" if sol <= 1869 else "DATA"
    return f"{NAVCAM_BASE}{branch}/SOL{sol:05d}/"


def stereo_count(row: dict, cache: Path) -> int:
    import re
    sol, site, drive = int(row["sol"]), int(row["site"]), int(row["drive"])
    try:
        html = request_bytes(navcam_folder(sol), cache / f"navcam-listing-{sol:05d}.html", timeout=30).decode(errors="ignore")
    except RuntimeError as exc:
        log(f"Sol {sol}: Navcam listing unavailable ({exc})")
        return 0
    station = f"{site:03d}{drive:04d}"
    xyz = set(re.findall(rf"NLB_\d{{9}}XYZLF{station}NCAM\d{{5}}M1\.IMG", html))
    return sum(name.replace("XYZLF", "RASLF") in html for name in xyz)


def check_stereo_counts(candidates: list[dict], cache: Path, workers: int) -> list[int]:
    """Check listings concurrently while continuously exposing useful progress."""
    started = time.monotonic()
    counts: dict[int, int] = {}
    total = len(candidates)
    with futures.ThreadPoolExecutor(max_workers=workers) as pool:
        pending = {}
        for row in candidates:
            sol = int(row["sol"])
            cached = (cache / f"navcam-listing-{sol:05d}.html").is_file()
            pending[pool.submit(stereo_count, row, cache)] = (sol, cached)
        completed = 0
        while pending:
            done, _ = futures.wait(pending, timeout=15, return_when=futures.FIRST_COMPLETED)
            if not done:
                elapsed = int(time.monotonic() - started)
                log(f"Navcam check is active: {completed}/{total} complete, "
                    f"{len(pending)} pending, {elapsed}s elapsed")
                continue
            for future in done:
                sol, cached = pending.pop(future)
                try:
                    frames = int(future.result())
                except Exception as exc:
                    frames = 0
                    log(f"Sol {sol}: unexpected listing failure ({exc})")
                counts[sol] = frames
                completed += 1
                source = "cache" if cached else "NASA"
                elapsed = int(time.monotonic() - started)
                log(f"Navcam [{completed}/{total}] Sol {sol}: {frames} stereo frame(s) "
                    f"from {source}; {elapsed}s elapsed")
    return [counts[int(row["sol"])] for row in candidates]


def connectivity(rows: list[dict], target: dict) -> tuple[float, int]:
    distances = sorted(distance_m(target, other) for other in rows if int(other["sol"]) != int(target["sol"]))
    return (distances[0] if distances else 9999.0, sum(value <= 100 for value in distances))


def write_csv(path: Path, rows: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fields = sorted({key for row in rows for key in row})
    with path.open("w", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, extrasaction="ignore")
        writer.writeheader(); writer.writerows(rows)


def build_ranking(repo: Path, args: argparse.Namespace, reports: Path) -> tuple[list[dict], dict]:
    app_data = json.loads((repo / "app/data.json").read_text())
    window = app_data["window"]
    cache = repo / "data/cache/colab_color_pipeline"
    waypoints = get_json(WAYPOINTS_URL, cache / "waypoints.json")
    all_rows = stop_rows(waypoints, args.sol_min, args.sol_max)
    candidates = [row for row in all_rows if in_window(row, window)]
    if not candidates:
        raise RuntimeError("No rover stops fall inside the configured planning window and sol range")
    log(f"Checking Navcam stereo for {len(candidates)} in-window stops with {args.workers} worker(s)")
    counts = check_stereo_counts(candidates, cache, args.workers)
    pre_rows = []
    for row, frames in zip(candidates, counts):
        nearest, cluster = connectivity(candidates, row)
        stereo_norm = min(1.0, frames / 18.0)
        neighbor_norm = max(0.0, 1.0-nearest/250.0)
        path_norm = 0.7*neighbor_norm + 0.3*min(1.0, cluster/4.0)
        pre_rows.append({**row, "sol": int(row["sol"]), "site": int(row["site"]), "drive": int(row["drive"]),
                         "stereo_frames": frames, "nearest_neighbor_m": round(nearest, 2),
                         "cluster_stops_100m": cluster, "stereo_norm": stereo_norm,
                         "path_norm": path_norm, "pre_score": 0.7*stereo_norm+0.3*path_norm})
    reconstructable = [row for row in pre_rows if row["stereo_frames"] > 0]
    reconstructable.sort(key=lambda row: (-row["pre_score"], row["sol"]))
    shortlist = reconstructable[:max(args.top * args.shortlist_multiplier, args.top)]
    if not shortlist:
        raise RuntimeError("No in-window stops have paired Navcam RAS/XYZ products")

    anchors = repo / "data/colab_color_work/ranking_anchors"
    if anchors.exists():
        shutil.rmtree(anchors)
    for row in shortlist:
        folder = anchors / f"sol{row['sol']}"
        folder.mkdir(parents=True)
        (folder / "stop.json").write_text(json.dumps(row, indent=2))
    audit_dir = reports / "ranking_audit"
    coverage_path = audit_dir / "coverage.json"
    audit_needed = args.refresh_metadata or not coverage_path.is_file()
    if not audit_needed:
        try:
            previous = json.loads(coverage_path.read_text())
            previous_sols = sorted(map(int, previous["config"]["sols"]))
            audit_needed = (bool(previous.get("incomplete"))
                            or previous_sols != sorted(row["sol"] for row in shortlist)
                            or int(previous["config"]["sol_window"]) != args.sol_window)
        except (OSError, ValueError, KeyError, TypeError, json.JSONDecodeError):
            audit_needed = True
    if audit_needed:
        if audit_dir.exists():
            shutil.rmtree(audit_dir)
        command = [sys.executable, str(repo / "navcam3d/audit_color_coverage.py"),
                   "--raw-root", str(anchors), "--sols", *map(str, [row["sol"] for row in shortlist]),
                   "--sol-window", str(args.sol_window), "--workers", str(args.workers),
                   "--output", str(audit_dir)]
        if args.refresh_metadata:
            command.append("--refresh")
        run(command, cwd=repo, check=False)
    if not coverage_path.is_file():
        raise RuntimeError("Mastcam ranking audit produced no coverage.json")
    coverage = json.loads(coverage_path.read_text())
    summaries = {int(row["target_sol"]): row for row in coverage["summary"]}
    ranked = []
    for row in shortlist:
        summary = summaries.get(row["sol"], {})
        color_images = int(summary.get("same_spot_window", 0))
        azimuth_bins = len(summary.get("same_spot_azimuth_bins", []))
        color_norm = 0.7*min(1.0, color_images/20.0) + 0.3*min(1.0, azimuth_bins/6.0)
        score = 100*(0.55*color_norm + 0.30*row["stereo_norm"] + 0.15*row["path_norm"])
        ranked.append({**row, "mastcam_same_station": color_images, "mastcam_azimuth_bins": azimuth_bins,
                       "color_norm": round(color_norm, 6), "score": round(score, 3),
                       "metadata_complete": not coverage.get("incomplete", False)})
    ranked = [row for row in ranked if row["mastcam_same_station"] > 0]
    ranked.sort(key=lambda row: (-row["score"], row["sol"]))
    for index, row in enumerate(ranked, 1):
        row["rank"] = index
    write_csv(reports / "ranking.csv", ranked)
    (reports / "ranking.json").write_text(json.dumps(ranked, indent=2, allow_nan=False))
    selected = ranked[:args.top]
    if not selected:
        raise RuntimeError("No reconstructable stop has confirmed same-station Mastcam RGB")
    log("Selected sols: " + ", ".join(f"{r['sol']} ({r['score']:.1f})" for r in selected))
    return selected, app_data


def valid_original(folder: Path, sol: int) -> bool:
    try:
        meta = json.loads((folder / "scene.json").read_text())
        blob = base64.b64decode((folder / "scene.b64.txt").read_bytes(), validate=True)
        n, f = int(meta["counts"]["vertices"]), int(meta["counts"]["faces"])
        expected = n*6+n+n+n+f*12
        return int(meta["sol"]) == sol and len(blob) == expected and (folder / "index.html").is_file()
    except (OSError, ValueError, KeyError, json.JSONDecodeError):
        return False


def register_original(app_data: dict, meta: dict) -> None:
    sol = int(meta["sol"])
    window = app_data["window"]
    stop = meta["stop"]
    x, y = projected_xy(float(stop["lat"]), float(stop["lon"]))
    cx, cy = projected_xy(float(window["lat"]), float(window["lon"]))
    half = float(window["size_m"]) / 2
    hazards = [[round(x-(cx-half)+h["east"], 2), round((cy+half)-y+h["south"], 2),
                h["height"], int(h["estimated"])] for h in meta.get("hazards", [])]
    entry = {"sol": sol, "folder": f"stops/sol{sol}", "x": round(x-(cx-half), 1),
             "y": round((cy+half)-y, 1), "elev": stop.get("elev_geoid", 0),
             "photos": len(meta["frames"]), "error": round(float(meta["summary"]["median_da_absrel"]), 4),
             "area_m2": round(float(meta["map"]["area_m2"])), "model": meta["depth_model"],
             "hazards": hazards}
    app_data["closeups"] = [row for row in app_data.get("closeups", []) if int(row["sol"]) != sol] + [entry]
    app_data["closeups"].sort(key=lambda row: int(row["sol"]))


def refresh_result_totals(app_data: dict) -> None:
    closeups = app_data.get("closeups", [])
    errors = sorted(float(row["error"]) for row in closeups)
    median = None
    if errors:
        middle = len(errors) // 2
        median = errors[middle] if len(errors) % 2 else (errors[middle-1] + errors[middle]) / 2
    previous = app_data.get("results", {})
    app_data["results"] = {
        "stops": len(closeups),
        "photos": sum(int(row["photos"]) for row in closeups),
        "area_m2": round(sum(float(row["area_m2"]) for row in closeups)),
        "rocks": sum(len(row.get("hazards", [])) for row in closeups),
        "tall_rocks": sum(1 for row in closeups for hazard in row.get("hazards", []) if hazard[2] >= 0.5),
        "median_error": median,
    }
    if "finetune" in previous:
        app_data["results"]["finetune"] = previous["finetune"]


def validate_variant(original: Path, variant: Path) -> dict:
    source = base64.b64decode((original / "scene.b64.txt").read_bytes(), validate=True)
    other = base64.b64decode((variant / "scene.b64.txt").read_bytes(), validate=True)
    if source != other:
        raise ValueError("variant geometry differs from original")
    meta = json.loads((variant / "scene.json").read_text())
    original_meta = json.loads((original / "scene.json").read_text())
    if {k: v for k, v in meta.items() if k not in ("variant", "colorization")} != original_meta:
        raise ValueError("variant changed original metadata")
    n = int(meta["counts"]["vertices"])
    color = meta["colorization"]
    rgb = base64.b64decode((variant / color["asset"]).read_bytes(), validate=True)
    mask = base64.b64decode((variant / color["mask_asset"]).read_bytes(), validate=True)
    if len(rgb) != 3*n or len(mask) != n or any(value not in (0, 1) for value in mask):
        raise ValueError("invalid RGB or mask dimensions")
    if sum(mask) < 25 or sum(mask) != int(color["colored_vertices"]):
        raise ValueError("inconsistent colored vertex count")
    if hashlib.sha256(source).hexdigest() != color["geometry_sha256"]:
        raise ValueError("geometry checksum mismatch")
    gray_offset = n*6
    for index, colored in enumerate(mask):
        if not colored and rgb[index*3:index*3+3] != bytes([source[gray_offset+index]])*3:
            raise ValueError("uncovered vertex is not original grayscale")
    return meta


def build_and_color(repo: Path, selected: list[dict], app_data: dict,
                    args: argparse.Namespace, reports: Path) -> tuple[list[dict], list[dict]]:
    missing = [row["sol"] for row in selected
               if args.rebuild_geometry or not valid_original(repo / f"app/stops/sol{row['sol']}", row["sol"])]
    if missing:
        command = [sys.executable, str(repo / "navcam3d/build_stop.py"), *map(str, missing)]
        run(command, cwd=repo, check=False)
    buildable = []
    for row in selected:
        folder = repo / f"app/stops/sol{row['sol']}"
        if valid_original(folder, row["sol"]):
            meta = json.loads((folder / "scene.json").read_text())
            register_original(app_data, meta)
            buildable.append(row)
        else:
            row["pipeline_error"] = "original reconstruction failed validation"
    selected_ids = {f"{row['sol']}-color" for row in buildable}
    app_data["closeup_variants"] = [row for row in app_data.get("closeup_variants", [])
                                        if row.get("id") not in selected_ids]
    refresh_result_totals(app_data)
    (repo / "app/data.json").write_text(json.dumps(app_data, indent=2))
    if not buildable:
        raise RuntimeError("None of the selected sols produced a valid original reconstruction")

    backup_root = repo / "data/colab_color_work/invalid_variant_backups"
    for row in buildable:
        original = repo / f"app/stops/sol{row['sol']}"
        variant = repo / f"app/stops/sol{row['sol']}-color"
        if variant.exists():
            try:
                validate_variant(original, variant)
            except (OSError, ValueError, KeyError, json.JSONDecodeError):
                backup_root.mkdir(parents=True, exist_ok=True)
                target = backup_root / f"{variant.name}-{int(time.time())}"
                variant.rename(target)
                log(f"Moved incompatible existing variant to {target}")
    batch_dir = reports / "color_batch"
    if batch_dir.exists():
        batch_dir = reports / f"color_batch-{datetime.now().strftime('%Y%m%d-%H%M%S')}"
    command = [sys.executable, str(repo / "navcam3d/colorize_all_stops.py"),
               "--sols", *map(str, [row["sol"] for row in buildable]),
               "--max-images", str(args.max_images), "--sol-window", str(args.sol_window),
               "--workers", str(args.workers), "--output", str(batch_dir)]
    run(command, cwd=repo, check=False)

    successful = []
    for row in buildable:
        try:
            meta = validate_variant(repo / f"app/stops/sol{row['sol']}",
                                    repo / f"app/stops/sol{row['sol']}-color")
            row["actual_color_coverage"] = meta["colorization"]["vertex_coverage"]
            row["actual_color_images"] = len(meta["colorization"]["images"])
            successful.append(row)
        except (OSError, ValueError, KeyError, json.JSONDecodeError) as exc:
            row["pipeline_error"] = f"color variant failed validation: {exc}"
    write_csv(reports / "final_results.csv", selected)
    (reports / "final_results.json").write_text(json.dumps(selected, indent=2, allow_nan=False))
    if not successful:
        raise RuntimeError("No selected sol produced a valid color variant")
    return successful, buildable


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(1024*1024):
            digest.update(chunk)
    return digest.hexdigest()


def package(repo: Path, successful: list[dict], originals: list[dict], args: argparse.Namespace,
            reports: Path) -> Path:
    output = args.output_dir.resolve()
    if output.exists():
        if not args.overwrite_output:
            raise RuntimeError(f"Output exists; use --overwrite-output: {output}")
        shutil.rmtree(output)
    staging = output.with_name(output.name + ".building")
    if staging.exists():
        shutil.rmtree(staging)
    (staging / "app/stops").mkdir(parents=True)
    for row in originals:
        name = f"sol{row['sol']}"
        shutil.copytree(repo / "app/stops" / name, staging / "app/stops" / name)
    for row in successful:
        name = f"sol{row['sol']}-color"
        shutil.copytree(repo / "app/stops" / name, staging / "app/stops" / name)
    shutil.copy2(repo / "app/data.json", staging / "app/data.json")
    shutil.copytree(reports, staging / "reports")
    revision_result = subprocess.run(["git", "rev-parse", "HEAD"], cwd=repo, check=False,
                                     stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
    manifest = {
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "repo_url": args.repo_url,
        "requested_revision": args.revision,
        "resolved_revision": revision_result.stdout.strip() or None,
        "embedded_pipeline_sha256": PIPELINE_PAYLOAD_SHA256,
        "configuration": {"top": args.top, "sol_min": args.sol_min, "sol_max": args.sol_max,
                          "max_images": args.max_images, "sol_window": args.sol_window,
                          "workers": args.workers},
        "sols": [{"sol": row["sol"], "rank": row["rank"], "ranking_score": row["score"],
                  "estimated_same_station_images": row["mastcam_same_station"],
                  "actual_color_coverage": row["actual_color_coverage"],
                  "actual_color_images": row["actual_color_images"]} for row in successful],
        "files": {},
    }
    (staging / "INSTALL.md").write_text(
        "# Install generated color coverage\n\n"
        "Copy the contents of this directory over the root of the same Marswalk repository revision.\n"
        "The included `app/data.json` registers every bundled original and `-color` stop.\n"
        "Existing unrelated files are not removed. Keep a backup if your local `app/data.json` has diverged.\n"
    )
    for path in sorted(staging.rglob("*")):
        if path.is_file():
            manifest["files"][str(path.relative_to(staging))] = {"bytes": path.stat().st_size,
                                                                   "sha256": sha256_file(path)}
    (staging / "manifest.json").write_text(json.dumps(manifest, indent=2, allow_nan=False))
    staging.rename(output)
    archive = Path(shutil.make_archive(str(output), "zip", root_dir=output.parent, base_dir=output.name))
    log(f"Bundle: {archive} ({archive.stat().st_size/1e6:.1f} MB)")
    return archive


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--repo-url", default=DEFAULT_REPO_URL)
    parser.add_argument("--repo-dir", type=Path, default=Path("/content/gale-marswalk-planner"))
    parser.add_argument("--revision", help="optional Git branch, tag, or commit")
    parser.add_argument("--output-dir", type=Path, default=Path("/content/color_coverage"))
    parser.add_argument("--top", type=int, default=14)
    parser.add_argument("--shortlist-multiplier", type=int, default=4)
    parser.add_argument("--sol-min", type=int)
    parser.add_argument("--sol-max", type=int)
    parser.add_argument("--sol-window", type=int, default=5)
    parser.add_argument("--max-images", type=int, default=20)
    parser.add_argument("--workers", type=int, default=2)
    parser.add_argument("--refresh-metadata", action="store_true")
    parser.add_argument("--rebuild-geometry", action="store_true")
    parser.add_argument("--overwrite-output", action="store_true")
    parser.add_argument("--skip-install", action="store_true")
    parser.add_argument("--allow-cpu", action="store_true")
    parser.add_argument("--download", action="store_true", help="trigger google.colab.files.download")
    args = parser.parse_args(argv)
    if args.top < 1 or args.shortlist_multiplier < 1 or args.workers < 1 or args.max_images < 1 or args.sol_window < 0:
        parser.error("top, shortlist multiplier, workers and max-images must be positive; sol-window nonnegative")
    if args.sol_min is not None and args.sol_max is not None and args.sol_min > args.sol_max:
        parser.error("--sol-min cannot exceed --sol-max")
    return args


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    ensure_dependencies(args.skip_install)
    import torch
    if not args.allow_cpu and not torch.cuda.is_available():
        raise RuntimeError("A Colab GPU runtime is required. Select Runtime > Change runtime type > GPU, or use --allow-cpu.")
    repo = prepare_repo(args)
    reports = repo / "data/colab_color_work/reports"
    reports.mkdir(parents=True, exist_ok=True)
    selected, app_data = build_ranking(repo, args, reports)
    successful, originals = build_and_color(repo, selected, app_data, args, reports)
    archive = package(repo, successful, originals, args, reports)
    log(f"Completed {len(successful)}/{len(selected)} selected sols")
    if args.download:
        try:
            from google.colab import files
            files.download(str(archive))
        except ImportError:
            log("google.colab is unavailable; download the ZIP from the printed path")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        log("Interrupted. Rerun the same command to reuse cached downloads and completed variants.")
        raise SystemExit(130)
